package com.example.starter.consent.dto;

import java.time.Instant;

import com.example.starter.consent.Purpose;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 保留冻结创建请求：对有效或已撤回代次创建法定保留冻结。
 *
 * @param requestId   幂等请求标识，同一 requestId 相同参数重试返回原结果
 * @param holdKey     冻结标识，全局唯一
 * @param subjectKey  主体标识（合成字符串）
 * @param purpose     用途：RESEARCH 研究 / PERSONALIZATION 个性化
 * @param epoch       被冻结的授权代次，从 1 开始
 * @param legalReason 法定事由，同一 epoch 同一事由只允许一个生效冻结
 * @param createdBy   创建人（保留角色操作人标识）
 * @param expiresAt   UTC 到期时刻（ISO-8601），必须晚于当前时刻
 */
public record CreateHoldRequest(
        @NotBlank @Size(max = 128) String requestId,
        @NotBlank @Size(max = 128) String holdKey,
        @NotBlank @Size(max = 128) String subjectKey,
        @NotNull Purpose purpose,
        @NotNull @Min(1) Integer epoch,
        @NotBlank @Size(max = 128) String legalReason,
        @NotBlank @Size(max = 128) String createdBy,
        @NotNull Instant expiresAt) {
}

package com.example.starter.consent.dto;

import java.time.Instant;

import com.example.starter.consent.HoldStatus;
import com.example.starter.consent.Purpose;

/**
 * 保留冻结响应：返回冻结标识、目标代次、法定事由、状态与 UTC 到期时刻。
 *
 * @param holdKey     冻结标识
 * @param subjectKey  主体标识（合成字符串）
 * @param purpose     用途：RESEARCH 研究 / PERSONALIZATION 个性化
 * @param epoch       被冻结的授权代次
 * @param legalReason 法定事由
 * @param status      状态：ACTIVE 生效 / RELEASED 已解除
 * @param createdBy   创建人（保留角色操作人标识）
 * @param expiresAt   UTC 到期时刻
 */
public record HoldResponse(
        String holdKey,
        String subjectKey,
        Purpose purpose,
        int epoch,
        String legalReason,
        HoldStatus status,
        String createdBy,
        Instant expiresAt) {
}

package com.example.starter.consent.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 保留冻结解除请求：须由不同于创建人的保留角色提交说明，解除记录不可变。
 *
 * @param requestId  幂等请求标识
 * @param holdKey    待解除的冻结标识
 * @param releasedBy 解除人（保留角色操作人标识），必须不同于创建人
 * @param note       解除说明，写入后不可变
 */
public record ReleaseHoldRequest(
        @NotBlank @Size(max = 128) String requestId,
        @NotBlank @Size(max = 128) String holdKey,
        @NotBlank @Size(max = 128) String releasedBy,
        @NotBlank @Size(max = 512) String note) {
}

package com.example.starter.consent.dto;

import java.time.Instant;

import com.example.starter.consent.HoldStatus;

/**
 * 保留冻结解除响应：解除结果与不可变解除记录。
 *
 * @param holdKey    冻结标识
 * @param status     状态，解除成功固定为 RELEASED
 * @param releasedBy 解除人（保留角色操作人标识）
 * @param releasedAt 解除时间（UTC）
 * @param note       解除说明
 */
public record ReleaseResponse(
        String holdKey,
        HoldStatus status,
        String releasedBy,
        Instant releasedAt,
        String note) {
}

